/// A registry version or enabled-extension requirement; not feature-bit validation.
#[derive(Debug, Clone, Copy)]
pub enum CapabilityRequirement {
	Core(u32),
	InstanceExtension(&'static std::ffi::CStr),
	DeviceExtension(&'static std::ffi::CStr),
}

#[derive(Debug)]
pub struct CommandMetadata {
	pub name: &'static str,
	pub alias_of: Option<&'static str>,
	pub dispatch: &'static str,
	/// Physical-device query, even though it uses instance dispatch.
	pub physical_device: bool,
	/// Alternatives of conjunctions for this exact command spelling.
	pub requirements: &'static [&'static [CapabilityRequirement]],
}

